        argv = ['/usr/bin/python3', '-I', '-B', str(HELPER / 'controller.py'), 'admit', unit]
    else:
        assert own == host / 'next_fixture_poststart.py' and unit is None
        assert sys.argv == [str(host / 'probe.py'), 'hook-post']
